function_name: swapExactJarForJar
code:     function swapExactJarForJar(
        address _fromJar,
        address _toJar,
        uint256 _fromJarAmount,
        uint256 _toJarMinAmount,
        address payable[] calldata _targets,
        bytes[] calldata _data
    ) external returns (uint256) {
        require(_targets.length == _data.length, "!length");
        for (uint256 i = 0; i < _targets.length; i++) {
            require(_targets[i] != address(0), "!converter");
            require(approvedJarConverters[_targets[i]], "!converter");
        }
        address _fromJarToken = IJar(_fromJar).token();
        address _toJarToken = IJar(_toJar).token();
        IERC20(_fromJar).safeTransferFrom(
            msg.sender,
            address(this),
            _fromJarAmount
        );
        uint256 _fromJarUnderlyingAmount = _fromJarAmount
            .mul(IJar(_fromJar).getRatio())
            .div(10**uint256(IJar(_fromJar).decimals()));
        uint256 _fromJarAvailUnderlying = IERC20(_fromJarToken).balanceOf(
            _fromJar
        );
        if (_fromJarAvailUnderlying < _fromJarUnderlyingAmount) {
            IStrategy(strategies[_fromJarToken]).withdrawForSwap(
                _fromJarUnderlyingAmount.sub(_fromJarAvailUnderlying)
            );
        }
        IERC20(_fromJar).safeApprove(_fromJar, 0);
        IERC20(_fromJar).safeApprove(_fromJar, _fromJarAmount);
        IJar(_fromJar).withdraw(_fromJarAmount);
        uint256 _fromUnderlyingBalance = IERC20(_fromJarToken).balanceOf(
            address(this)
        );
        uint256 _convenienceFee = _fromUnderlyingBalance.mul(convenienceFee).div(
            convenienceFeeMax
        );
        if (_convenienceFee > 1) {
            IERC20(_fromJarToken).safeTransfer(devfund, _convenienceFee.div(2));
            IERC20(_fromJarToken).safeTransfer(treasury, _convenienceFee.div(2));
        }
        for (uint256 i = 0; i < _targets.length; i++) {
            _execute(_targets[i], _data[i]);
        }
        uint256 _toBal = IERC20(_toJarToken).balanceOf(address(this));
        IERC20(_toJarToken).safeApprove(_toJar, 0);
        IERC20(_toJarToken).safeApprove(_toJar, _toBal);
        IJar(_toJar).deposit(_toBal);
        uint256 _toJarBal = IJar(_toJar).balanceOf(address(this));
        if (_toJarBal < _toJarMinAmount) {
            revert("!min-jar-amount");
        }
        IJar(_toJar).transfer(msg.sender, _toJarBal);
        return _toJarBal;
    }
vulnerability: Missing validation of _fromJar allows forced strategy withdrawal and donation attack
reason: The function trusts the user-supplied _fromJar address and calls IJar(_fromJar).token(), getRatio(), decimals(), and IStrategy(strategies[_fromJarToken]).withdrawForSwap(...) without verifying that _fromJar is the legitimate jar for _fromJarToken (i.e., jars[_fromJarToken] == _fromJar). An attacker can deploy a malicious contract implementing the IJar interface that returns a legitimate token such as DAI, a controlled getRatio(), and a controlled decimals(). Its transferFrom() can be a no-op. The attacker calls swapExactJarForJar with this malicious _fromJar and a large _fromJarAmount. The Controller computes a large _fromJarUnderlyingAmount and, because the malicious jar has insufficient real underlying, calls the legitimate strategy's withdrawForSwap() for the difference. In typical Yearn-style strategies, withdrawForSwap() withdraws real underlying and transfers it to the legitimate jar registered in jars[want]. This is a donation to the legitimate jar, increasing the underlying value per jar share. The attacker can first acquire a large amount of legitimate jar shares (e.g., via flash loan), trigger this donation, and then redeem the shares for a profit, draining strategy funds from other jar holders. This is a critical theft-of-funds vulnerability.
------------------
